<template>
  <div
    class="sc"
    @mouseenter="pause"
    @mouseleave="resume"
    @touchstart="onTouchStart"
    @touchend="onTouchEnd"
  >
    <div class="sc-viewport">
      <div class="sc-track" :style="trackStyle">
        <div class="sc-slide" v-for="(item, i) in items" :key="i">
          <slot name="slide" :item="item" :index="i" :active="i === index" />
        </div>
      </div>
    </div>

    <button
      v-if="items.length > 1"
      type="button"
      class="sc-arrow sc-prev"
      aria-label="이전"
      @click="prev"
    >‹</button>
    <button
      v-if="items.length > 1"
      type="button"
      class="sc-arrow sc-next"
      aria-label="다음"
      @click="next"
    >›</button>

    <div v-if="items.length > 1" class="sc-dots">
      <button
        v-for="(item, i) in items"
        :key="i"
        type="button"
        class="sc-dot"
        :class="{ active: i === index }"
        :aria-label="`${i + 1}번째 항목`"
        @click="go(i)"
      ></button>
    </div>
  </div>
</template>

<script>
export default {
  name: 'SiteCarousel',
  props: {
    items: { type: Array, required: true },
    // 0이면 자동 재생 안 함, 양수면 해당 ms 간격으로 자동 전환
    interval: { type: Number, default: 0 }
  },
  data () {
    return { index: 0, timer: null }
  },
  computed: {
    trackStyle () {
      return { transform: `translateX(-${this.index * 100}%)` }
    }
  },
  mounted () {
    this.startAuto()
  },
  beforeDestroy () {
    this.clearAuto()
  },
  methods: {
    go (i) {
      const n = this.items.length
      this.index = (i + n) % n
    },
    next () {
      this.go(this.index + 1)
    },
    prev () {
      this.go(this.index - 1)
    },
    startAuto () {
      if (this.interval > 0 && this.items.length > 1) {
        this.timer = setInterval(this.next, this.interval)
      }
    },
    clearAuto () {
      if (this.timer) {
        clearInterval(this.timer)
        this.timer = null
      }
    },
    pause () {
      this.clearAuto()
    },
    resume () {
      this.startAuto()
    },
    onTouchStart (e) {
      this.touchX = e.changedTouches[0].clientX
    },
    onTouchEnd (e) {
      if (this.touchX == null) return
      const dx = e.changedTouches[0].clientX - this.touchX
      if (Math.abs(dx) > 40) {
        dx < 0 ? this.next() : this.prev()
      }
      this.touchX = null
    }
  }
}
</script>

