const SHOT_FILES = ['01_list.png', '02_article.png', '03_settings.png', /* '04_media.png', */ '05_video.png']

export default {
  name: 'NewsFilter',
  components: { SiteNav, SiteCarousel },
  props: {
    lang: { type: String, default: 'ko' }
  },
  data () {
    return { activeEdition: 'daum', zoomedQr: null }
  },
  computed: {
    dark () {
      return this.$store.getters.isDark
    },
    t () {
      return CONTENT[this.lang] || CONTENT.ko
    },
    baseUrl () {
      return process.env.BASE_URL || '/'
    },
    playLogo () {
      return this.baseUrl + 'images/logo.playstore.png'
    },
    editions () {
      const nf = this.baseUrl + 'newsfilter/'
      return [
        { key: 'daum', accent: '#3b5bf5', playUrl: PLAY.daum, feature: nf + 'daum_feature.png', icon: nf + 'daum_icon.png', qr: nf + 'daum_qr.png', ...this.t.editions.daum },
