      ]
    },
    currentShots () {
      return SHOT_FILES.map((file, i) => ({
        src: this.baseUrl + 'newsfilter/' + this.activeEdition + '_' + file,
        caption: this.t.shotCaptions[i]
      }))
    }
  },
  methods: {
    openQr (edition) {
      this.zoomedQr = { qr: edition.qr, name: edition.name }
    },
    closeQr () {
      this.zoomedQr = null
    },
    onKeydown (e) {
      if (e.key === 'Escape') this.closeQr()
    }
  },
  mounted () {
    document.addEventListener('keydown', this.onKeydown)
  },
  beforeDestroy () {
    document.removeEventListener('keydown', this.onKeydown)
  }
}
